import org.junit.Test
import org.junit.Assert

class Tests {
    @Test
    fun testDescending() {
        Assert.assertEquals(listOf(91, 72, 45, 38), sortDescending(listOf(45, 72, 38, 91)))
    }

    @Test
    fun testAlreadyDescending() {
        Assert.assertEquals(listOf(3, 2, 1), sortDescending(listOf(3, 2, 1)))
    }

    @Test
    fun testSingle() {
        Assert.assertEquals(listOf(5), sortDescending(listOf(5)))
    }
}
